  /* ── Day 1 Progress Ring Animation ── */
  var CIRC = 119.38; // 2 * PI * 19

  // Animate a ring's stroke-dashoffset from current to target percentage
  // pct: 0 = empty, 1 = full circle
  function animateRing(fg, targetPct, duration, cb) {
    var startOffset = parseFloat(fg.style.strokeDashoffset) || CIRC;
    var endOffset = CIRC * (1 - targetPct);
    var start = null;
    function tick(ts) {
      if (!start) start = ts;
      var p = Math.min((ts - start) / duration, 1);
      // ease-out cubic
      var eased = 1 - Math.pow(1 - p, 3);
      fg.style.strokeDashoffset = String(startOffset + (endOffset - startOffset) * eased);
      if (p < 1) {
        requestAnimationFrame(tick);
      } else {
        if (cb) cb();
      }
    }
    requestAnimationFrame(tick);
  }

  var _welcomeTimelineRan = false;
  function runWelcomeTimelineAnim() {
    if (_welcomeTimelineRan) return;
    _welcomeTimelineRan = true;
    var container = document.getElementById('wfTimeline');
    if (!container) return;
    var steps = container.querySelectorAll('.d1-step');
    var line = container.querySelector('.d1-progress-line-active');
    if (!steps.length) return;

    // Read original states
    var origStates = [];
    steps.forEach(function(s, i) {
      if (s.classList.contains('done') || s.classList.contains('filled')) {
        origStates[i] = 'done';
      } else {
        origStates[i] = 'pending';
      }
    });

    // Reset all to not-started
    steps.forEach(function(s) {
      s.classList.remove('filled', 'in-progress', 'not-started', 'done', 'pending');
      s.classList.add('not-started');
      var fg = s.querySelector('.d1-ring-fg');
      if (fg) { fg.style.strokeDashoffset = String(CIRC); fg.style.stroke = ''; }
      var icon = s.querySelector('.d1-step-icon');
      if (icon) { icon.style.background = ''; icon.style.color = ''; }
      var ringBg = s.querySelector('.d1-ring-bg');
      if (ringBg) ringBg.style.stroke = '';
    });
    if (line) line.style.height = '0';

    // Build queue of steps to animate
    var queue = [];
    var firstPending = true;
    steps.forEach(function(step, i) {
      if (origStates[i] === 'done') {
        queue.push({ step: step, i: i, type: 'done' });
      } else if (firstPending) {
        queue.push({ step: step, i: i, type: 'pending' });
        firstPending = false;
      }
    });

    // Animation sequence per "done" step:
    //   1. Ring outline draws (0→100%)
    //   2. Icon fills orange (ring hides)
    //   3. Line below grows to next step (0%→100% height)
    //   4. → next step
    // For "pending" step: ring draws to 50% and stops

    function runNext(qi) {
      if (qi >= queue.length) return;
      var item = queue[qi];
      var fg = item.step.querySelector('.d1-ring-fg');
      var icon = item.step.querySelector('.d1-step-icon');
      var ringBg = item.step.querySelector('.d1-ring-bg');

      if (item.type === 'done') {
        // Step 1: Draw ring outline (500ms)
        item.step.classList.remove('not-started');
        item.step.classList.add('in-progress');
        animateRing(fg, 1.0, 500, function() {
          // Step 2: Icon fills orange (ring disappears)
          setTimeout(function() {
            item.step.classList.remove('in-progress');
            item.step.classList.add('filled');
            /* Black glyph, not white — Yuan, 4 Sep: "icon 全部变成黑色". This
               inline write is the one that matters: it outranks every
               stylesheet rule (ids included), so the scoped CSS below would
               have had no effect on its own. Same orange-disc/black-glyph pair
               the family timeline uses, so the two read as one component. */
            if (icon) { icon.style.background = '#ff550c'; icon.style.color = '#141410'; }
            if (fg) fg.style.stroke = 'transparent';
            if (ringBg) ringBg.style.stroke = 'transparent';

            // Step 3: Line grows down to next step (350ms transition in CSS)
            setTimeout(function() {
              // Line height = first step's centre to the NEXT step's centre.
              // Rows are 72px (the 60px in the CSS above is overridden by the
              // later .broker-progress .d1-step rule), so the step is 72 —
              // at 60 the orange stopped 12px short of each icon. 8/20.
              var targetH = (item.i + 1) * 72;
              if (line) line.style.height = targetH + 'px';

              // Wait for line to finish growing, then animate next step
              setTimeout(function() { runNext(qi + 1); }, 400);
            }, 150);
          }, 150);
        });
      } else {
        // Pending: ring draws to 50% and holds
        item.step.classList.remove('not-started');
        item.step.classList.add('in-progress');
        animateRing(fg, 0.5, 600, null);
      }
    }

    // Start with first step after a short delay
    setTimeout(function() { runNext(0); }, 300);
  }

  function runD1ProgressAnim() {
    var steps = document.querySelectorAll('#d1Progress .d1-step');
    var line = document.getElementById('d1LineActive');
    if (!steps.length) return;

    // Reset all steps to "not started" state
    steps.forEach(function(s) {
      s.classList.remove('filled', 'in-progress', 'not-started');
      s.classList.add('not-started');
      var fg = s.querySelector('.d1-ring-fg');
      if (fg) fg.style.strokeDashoffset = String(CIRC);
      var icon = s.querySelector('.d1-step-icon');
      if (icon) icon.style.background = '';
    });
    if (line) line.style.height = '0';

    // Build animation queue
    var queue = [];
    var firstPending = true;
    steps.forEach(function(step, i) {
      var isDone = step.classList.contains('done');
      if (isDone) {
        queue.push({ step: step, i: i, type: 'done' });
      } else if (firstPending) {
        queue.push({ step: step, i: i, type: 'pending' });
        firstPending = false;
      }
    });

    // Run queue sequentially with 3-state transitions
    function runNext(qi) {
      if (qi >= queue.length) return;
      var item = queue[qi];
      var fg = item.step.querySelector('.d1-ring-fg');

      if (item.type === 'done') {
        // State 1 → 2: not-started → in-progress (ring grows)
        item.step.classList.remove('not-started');
        item.step.classList.add('in-progress');
        animateRing(fg, 1.0, 500, function() {
          // State 2 → 3: in-progress → completed (fill orange)
          setTimeout(function() {
            item.step.classList.remove('in-progress');
            item.step.classList.add('filled');
            // Grow line to next step
            setTimeout(function() {
              var nextLineH = (item.i + 1) * 72;
              if (line) line.style.height = nextLineH + 'px';
              // Start next step after line grows
              setTimeout(function() { runNext(qi + 1); }, 300);
            }, 150);
          }, 200);
        });
      } else {
        // Pending: not-started → in-progress (ring grows, stays)
        item.step.classList.remove('not-started');
        item.step.classList.add('in-progress');
        animateRing(fg, 0.5, 600, null);
      }
    }

    // Start after a brief pause
    setTimeout(function() { runNext(0); }, 300);
  }

  /* ═══════ STORY: scroll-snap card transitions ═══════ */
  var storyInited = false;
  function initStoryCards() {
    if (storyInited) return;
    storyInited = true;

    var N = 7, CARD_MAX = 660, PILL_H = 70, GAP = 8, ACTIVE_Y = 120, PEEK_GAP = 8;
    var stage = document.getElementById('storyStage');
    var cards = stage.querySelectorAll('.s-card');
    var summaryTitle = document.getElementById('storySummaryTitle');
    var ctaWrap = document.getElementById('storyCtaWrap');
    var screen = document.getElementById('storyScreen');

    var hasSeenSummary = false;
    var expandedFromSummary = null;
    var activeIdx = 0;

    // Build tickers
    var STEPS = 8;
    document.querySelectorAll('#storyScreen .s-ticker').forEach(function(el) {
      var targetStr = el.textContent.trim();
      if (!/\d/.test(targetStr)) return;
      var digitsOnly = targetStr.replace(/\D/g, '');
      var targetNum = parseInt(digitsOnly, 10);
      var len = digitsOnly.length;
      var startNum = Math.max(0, targetNum - STEPS);
      var actualSteps = targetNum - startNum;
      var seq = [];
      for (var n = startNum; n <= targetNum; n++) {
        seq.push(String(n).padStart(len, '0'));
      }
      var html = [];
      var digitIdx = 0;
      for (var pos = 0; pos < targetStr.length; pos++) {
        var ch = targetStr[pos];
        if (/\d/.test(ch)) {
          var reel = seq.map(function(s) { return s[digitIdx]; });
          var allSame = reel.every(function(d) { return d === reel[0]; });
          if (allSame) {
            html.push('<span class="s-char">' + ch + '</span>');
          } else {
            var reelDigits = reel.map(function(d) { return '<span>' + d + '</span>'; }).join('');
            html.push('<span class="s-digit" style="--reel-steps:' + actualSteps + '"><span class="s-reel">' + reelDigits + '</span></span>');
          }
          digitIdx++;
        } else {
          html.push('<span class="s-char">' + ch + '</span>');
        }
      }
      el.innerHTML = html.join('');
    });

    function render(active) {
      var inSummary = active >= N;
      for (var j = 0; j < N; j++) { cards[j].classList.remove('active'); cards[j].classList.remove('expanded-card'); }

      if (inSummary) {
        var top = ACTIVE_Y + 70;
        for (var j = 0; j < N; j++) {
          var isExp = (expandedFromSummary === j);
          if (isExp) {
            cards[j].classList.add('expanded-card');
            cards[j].style.setProperty('--top', ACTIVE_Y + 'px');
            cards[j].style.setProperty('--h', CARD_MAX + 'px');
            cards[j].style.zIndex = 100;
            cards[j].classList.remove('tappable');
            cards[j].classList.add('active');
          } else {
            cards[j].style.setProperty('--top', top + 'px');
            cards[j].style.setProperty('--h', PILL_H + 'px');
            cards[j].style.zIndex = 30 - j;
            cards[j].style.opacity = (expandedFromSummary !== null) ? '0.35' : '1';
            cards[j].classList.toggle('tappable', expandedFromSummary === null);
          }
          top += PILL_H + GAP;
        }
        summaryTitle.classList.toggle('visible', expandedFromSummary === null);
        ctaWrap.classList.toggle('visible', expandedFromSummary === null);
        hasSeenSummary = true;
        return;
      }

      summaryTitle.classList.remove('visible');
      ctaWrap.classList.remove('visible');

      for (var j = 0; j < N; j++) {
        cards[j].classList.remove('tappable');
        cards[j].style.opacity = '1';
        var t, h;
        if (j < active) {
          var offsetIdx = active - j;
          t = ACTIVE_Y - offsetIdx * (PILL_H + GAP);
          h = PILL_H;
        } else if (j === active) {
          t = ACTIVE_Y;
          h = CARD_MAX;
          cards[j].classList.add('active');
        } else if (j === active + 1) {
          t = ACTIVE_Y + CARD_MAX + PEEK_GAP;
          h = CARD_MAX;
        } else {
          t = ACTIVE_Y + CARD_MAX + PEEK_GAP + (j - active - 1) * 220;
          h = 0;
        }
        cards[j].style.setProperty('--top', t + 'px');
        cards[j].style.setProperty('--h', h + 'px');
        cards[j].style.zIndex = 30 - j;
      }
    }

    cards[0].classList.add('skip-stag');
    for (var j = 1; j < N; j++) {
      cards[j].style.setProperty('--top', 'calc(100vh + 100px)');
      cards[j].style.setProperty('--h', '660px');
    }
    void cards[1].offsetHeight;

    render(activeIdx);
    requestAnimationFrame(function() {
      requestAnimationFrame(function() {
        cards[0].classList.remove('skip-stag');
      });
    });

    // Ticker ticked tracking
    cards.forEach(function(card) {
      var firstReel = card.querySelector('.s-ticker .s-digit .s-reel');
      if (!firstReel) return;
      var handler = function(e) {
        if (e.propertyName !== 'transform') return;
        card.classList.add('ticked');
        firstReel.removeEventListener('transitionend', handler);
      };
      firstReel.addEventListener('transitionend', handler);
    });

    // Tappable cards in summary
    cards.forEach(function(card, j) {
      card.addEventListener('click', function() {
        if (!card.classList.contains('tappable')) return;
        expandedFromSummary = j;
        render(N);
      });
    });

    // Collapse expanded card back to list view
    window.collapseExpandedCard = function(e) {
      e.stopPropagation();
      expandedFromSummary = null;
      render(N);
    };

    // Scroll handler
    function onScroll() {
      var y = screen.scrollTop;
      var vh = Math.max(screen.clientHeight, 852);
      var raw = y / vh;
      var idx = Math.min(N, Math.max(0, Math.round(raw)));
      if (idx !== activeIdx) {
        activeIdx = idx;
        render(activeIdx);
      }
    }
    screen.addEventListener('scroll', onScroll, { passive: true });

    // Store reset function
    window._storyReset = function() {
      activeIdx = 0;
      expandedFromSummary = null;
      hasSeenSummary = false;
      screen.scrollTop = 0;
      render(0);
    };
  }

  function closeStoryScreen() {
    var scr = document.getElementById('storyScreen');
    scr.classList.remove('story-scrollable');
    if (window._storyReset) window._storyReset();
    closeScreen('storyScreen');
  }

