  /* Data removal card: stacked growth chart + headline tick (ported from 03-active) */
  (function(){
    var COLS = 31;
    var MAXH = 123;   /* the frame's tallest bar inside the 140px column */
    var COLORS = ['#00C876', '#FFD447', '#E172EB', '#0067FF', '#003677'];
    var FRACS  = [0.30, 0.16, 0.20, 0.17, 0.17];

    function buildChart(){
      var chart = document.getElementById('drChart');
      if (!chart || chart.childElementCount) return;
      for (var i = 0; i < COLS; i++) {
        var col = document.createElement('div'); col.className = 'dr-col';
        var stack = document.createElement('div'); stack.className = 'dr-stack';
        var total = Math.max(3, Math.round(MAXH * Math.pow((i + 1) / COLS, 1.35)));
        stack.style.height = total + 'px';
        stack.style.transitionDelay = (i * 22) + 'ms';
        for (var sgi = 0; sgi < COLORS.length; sgi++) {
          var seg = document.createElement('div');
          seg.style.background = COLORS[sgi];
          seg.style.width = '3px';
          seg.style.height = Math.max(0, Math.round(total * FRACS[sgi])) + 'px';
          if (sgi === COLORS.length - 1) seg.style.flex = '1 0 0';
          stack.appendChild(seg);
        }
        col.appendChild(stack);
        chart.appendChild(col);
      }
    }

    function animateCard(){
      var card = document.getElementById('drCard');
      if (!card || card._drDone) return;
      card._drDone = true;
      card.classList.add('dr-chart-anim');
      var rec = document.getElementById('drRecords');
      var sit = document.getElementById('drSites');
      if (typeof setRollNumber === 'function') {
        /* 152 = the five category bars below, added up. */
        if (rec) setRollNumber(rec, (152).toLocaleString());
        if (sit) sit.textContent = '64';   /* no longer shown on the small card */
      } else {
        if (rec) rec.textContent = '152';
        if (sit) sit.textContent = '64';
      }
    }

    buildChart();
    window.addEventListener('load', function(){ setTimeout(animateCard, 300); });
  })();

