  // SSN tile: after it stays in view for 5s, the radar "finds" one event
  (function() {
    var frame = document.querySelector('.ssn-card iframe');
    if (!frame || !('IntersectionObserver' in window)) return;
    var timer = null, fired = false;
    var io = new IntersectionObserver(function(entries) {
      entries.forEach(function(en) {
        if (fired) return;
        if (en.isIntersecting && en.intersectionRatio >= 0.6) {
          if (!timer) timer = setTimeout(function() {
            fired = true;
            try { frame.contentWindow.postMessage({ type: 'ssn-event' }, '*'); } catch (e) {}
            io.disconnect();
          }, 5000);
        } else if (timer) { clearTimeout(timer); timer = null; }
      });
    }, { threshold: [0, 0.6, 1] });
    io.observe(frame);
  })();

