  /* Global rule: big numbers tick up live (Robinhood-style rolling digits).
     Total Removed + category rows + "today" pill drift upward slowly. */
  (function(){
    function start(){
      var totalEl = document.querySelector('#removalHistory .rh-total-num');
      var rowVals = document.querySelectorAll('#removalHistory .mr-cat-val');
      var bars = document.querySelectorAll('#removalHistory .mr-cat-bar-fg');
      if (!totalEl || !rowVals.length) return;
      var vals = Array.prototype.map.call(rowVals, function(el){ return parseInt(el.dataset.target || el.textContent.replace(/,/g,'')) || 0; });
      var total = parseInt(totalEl.dataset.target || totalEl.textContent.replace(/,/g,'')) || 0;
      var pill = document.querySelector('#removalHistory .mr-pill');
      var todayN = pill ? (parseInt((pill.textContent.match(/\d+/) || [4])[0]) || 4) : 4;
      setInterval(function(){
        if (document.hidden) return;
        var i = Math.floor(Math.random() * vals.length);
        vals[i] += 1; total += 1; todayN += 1;
        rowVals[i].dataset.target = vals[i];
        totalEl.dataset.target = total;
        if (typeof setRollNumber === 'function') {
          /* only roll if the open-animation has already populated the numbers */
          if (totalEl.textContent.replace(/,/g,'') !== '0') {
            setRollNumber(rowVals[i], String(vals[i]));
            setRollNumber(totalEl, total.toLocaleString());
          }
        }
        var mx = Math.max.apply(null, vals);
        bars.forEach && Array.prototype.forEach.call(bars, function(b, k){
          var w = Math.round(vals[k] / mx * 100);
          b.dataset.w = w;
          if (b.style.width && b.style.width !== '0px') b.style.width = w + '%';
        });
        if (pill) {
          var svg = pill.querySelector('svg');
          pill.innerHTML = '';
          if (svg) pill.appendChild(svg);
          pill.appendChild(document.createTextNode(' ' + todayN + ' Today'));
        }
      }, 5000);
    }
    window.addEventListener('load', function(){ setTimeout(start, 2500); });
  })();

