/* ── Tab bridge for index.html ──────────────────────────────────────────────
   Lets the launcher sidebar drive the phone (window.showTab) and keeps the
   sidebar dot in sync when the bottom nav is tapped inside the phone. */
(function () {
  var TABS = {
    home:       { screen: null,             label: 'Home'    },
    activity:   { screen: 'activityScreen', label: 'Activity'},
    vaults:     { screen: 'vaultsScreen',   label: 'Vault'   },
    idcard:     { screen: 'idcardScreen',   label: 'ID card' },
    profile:    { screen: 'profileScreen',  label: 'Profile' }
    /* Monitoring is deliberately absent — see the redirect in goTab. */
  };
  var ALL = ['activityScreen', 'idcardScreen', 'vaultsScreen', 'profileScreen'];

  /* Tab destinations hard-cut — no slide. Suppressing the transition on the
     outgoing screen for one frame stops Monitoring from sliding away and
     revealing the incoming tab from behind it. */
  function goTab(name) {
    /* index.html's sidebar still lists Monitoring, and so does the Home tile.
       Data removal is a pushed screen now: land on Home first, then push, so no
       tab root is left open underneath at the same z-index. */
    if (name === 'monitoring') { goTab('home'); openScreen('monitorScreen'); return; }
    var t = TABS[name];
    if (!t) return;

    var cut = [];
    ALL.forEach(function (id) {
      var el = document.getElementById(id);
      if (el && id !== t.screen && el.classList.contains('open')) {
        el.classList.add('tab-cut');
        cut.push(el);
      }
    });

    cut.forEach(function (el) { closeScreen(el.id); });
    /* The arriving root is a cut too. A tab is a cut, not a push — but block 42
       animates anything that gains .open, and which screens ARE tab roots
       differs per build: the 4-tab builds send Vault to #idcardScreen (named in
       that block's SKIP list), the 5-tab build sends it to #vaultsScreen, which
       in the other two is a pushed page and must keep its push. So rather than
       listing ids there, the incoming screen wears the same .tab-cut the
       outgoing ones already wear, and block 42 skips the animation for THIS
       transition only. Yuan, 23 Aug: "V3, when I tap Vault, the page slides in;
       it's a main navigation tab page, should be a hard cut." */
    var into = t.screen ? document.getElementById(t.screen) : null;
    if (into) { into.classList.add('tab-cut'); cut.push(into); }
    if (t.screen) openScreen(t.screen);
    else if (typeof syncNavActive === 'function') syncNavActive();

    var nav = document.querySelector('.bottom-nav');
    if (nav) nav.classList.remove('hidden');

    // Vaults owns its own "+" FAB, so the app's AI FAB steps aside. Entering
    // the tab always lands on the vault itself, never on an item still open.
    document.body.classList.toggle('vaults-open', name === 'vaults');
    document.body.classList.toggle('idcard-open', name === 'idcard');
    document.body.classList.remove('nav-out', 'nav-down', 'fab-wait');
    if (typeof window.vtResetVaults === 'function') window.vtResetVaults();
    if (typeof window.icResetCards === 'function') window.icResetCards();

    // Restore transitions once the closed position has been committed, so
    // screens opened from a Home tile still animate normally.
    if (cut.length) {
      void document.body.offsetHeight; // force reflow
      requestAnimationFrame(function () {
        cut.forEach(function (el) { el.classList.remove('tab-cut'); });
      });
    }
    sync();
  }
  window.goTab = goTab;
  window.showTab = goTab; // index.html sidebar calls this name

  function currentTab() {
    for (var k in TABS) {
      var s = TABS[k].screen;
      if (s && document.getElementById(s) && document.getElementById(s).classList.contains('open')) return k;
    }
    return 'home';
  }

  var lastSent = null;
  function sync() {
    var t = currentTab();
    if (t === lastSent) return;
    lastSent = t;
    try { window.parent.postMessage({ type: 'tabSync', tab: t }, '*'); } catch (e) {}
  }
  // Honour ?tab= on load.
  function init() {
    var tab = new URLSearchParams(location.search).get('tab');
    if (tab && TABS[tab]) showTab(tab);
    lastSent = currentTab();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();

