      while (_ed && !_ed.classList.contains('av-group')) _ed = _ed.previousElementSibling;
      window.vtOpenMailRow({ t:_et ? _et.textContent.trim() : '', s:_es ? _es.textContent.trim() : '',
        r:_ed ? _ed.textContent.trim() : '', picRaw:_ei ? _ei.getAttribute('src') : ''
      }, _mailRow.querySelector('.av-av'), 'you');
