            if (frame < c.at) { c.el.textContent = CH[Math.floor(Math.random() * CH.length)]; return; }
            if (frame < c.at + 3) { c.el.textContent = c.ch; c.el.className = 'settling'; return; }
            c.el.textContent = c.ch; c.el.className = '';
