/* ── Nav hides on scroll down, returns on scroll up ────────────────────────
   Home, Activity and Monitoring get this from the app's own handler, which
   only watches window and `.screen` elements. Vaults and ID Card scroll inside
   their own panes, so they need the same behaviour wiring up by hand. */
(function () {
  var PANES = ['vtL2Scroll', 'vtL3Scroll', 'icL1Scroll', 'icL2Scroll'];

  function watch(el) {
    var last = 0, ticking = false;
    el.addEventListener('scroll', function () {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(function () {
        ticking = false;
        var y = el.scrollTop;
        if (Math.abs(y - last) < 6) return;
        /* the nav always returns at the very top and at the very bottom */
        var atEnd = el.scrollHeight - (y + el.clientHeight) < 24;
        document.body.classList.toggle('nav-down', !atEnd && y > last && y > 60);
        last = y;
      });
    }, { passive: true });
  }

  function init() {
    PANES.forEach(function (id) {
      var el = document.getElementById(id);
      if (el) watch(el);
    });
    /* switching tabs always brings it back */
    document.querySelectorAll('.bottom-nav .nav-item').forEach(function (b) {
      b.addEventListener('click', function () { document.body.classList.remove('nav-down'); });
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();

