/* ── Fit the desktop phone frame to the window ─────────────────────────────
   Below 500px the frame is full-bleed and needs nothing. Above it, the frame
   is a fixed 390x844 device mock; rather than making every screen responsive
   we scale the whole frame down so it always fits, however short the window.
   The 24px bezel (two box-shadow rings) and a 24px margin are budgeted in. */
(function () {
  var BEZEL = 24, MARGIN = 24, W = 390, H = 844;
  /* Must match the CSS: the frame only exists where there's room for it and a
     real pointer. On a phone or tablet the app runs full-bleed and is not
     scaled at all. */
  var FRAMED = '(min-width: 500px) and (hover: hover) and (pointer: fine)';
  function isFramed() {
    return window.matchMedia ? window.matchMedia(FRAMED).matches : window.innerWidth >= 500;
  }

  function fitPhoneFrame() {
    var root = document.documentElement;
    if (!isFramed()) { root.style.removeProperty('--pf-scale'); return; }
    var scale = Math.min(
      1,
      (window.innerHeight - BEZEL - MARGIN) / H,
      (window.innerWidth  - BEZEL - MARGIN) / W
    );
    root.style.setProperty('--pf-scale', Math.max(scale, 0.3));
  }

  window.fitPhoneFrame = fitPhoneFrame;
  fitPhoneFrame();
  window.addEventListener('resize', fitPhoneFrame, { passive: true });
  window.addEventListener('orientationchange', fitPhoneFrame);
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fitPhoneFrame);
})();

