/* ── FAB clearance ────────────────────────────────────────────────────────
   The FABs used to offset by --nav-h, but --nav-h and .bottom-nav's height are
   declared separately (and switch on different media queries), so the two
   could disagree and the button ended up tucked behind the bar. Measure the
   nav that is actually on screen and sit exactly 20px above it. */
(function () {
  /* 32px of clear air above the tab bar — the same gap the button keeps from the
     frame's own edge when there is no bar. */
  var GAP = 32;
  function place() {
    var nav = document.querySelector('.bottom-nav');
    if (!nav) return;
    var h = nav.offsetHeight;
    if (!h) return;
    document.documentElement.style.setProperty('--fab-gap', (h + GAP) + 'px');
  }
  place();
  window.addEventListener('resize', place, { passive: true });
  window.addEventListener('orientationchange', place);
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', place);
  else place();
  window.addEventListener('load', place);
  if (window.ResizeObserver) {
    var nav = document.querySelector('.bottom-nav');
    if (nav) new ResizeObserver(place).observe(nav);
  }
})();

