/* ══ DRAG-TO-SCROLL for the newer carousels ══════════════════════════════
   On a phone these already swipe — overflow-x: auto does it for free. On a
   desktop there is no swipe, and several of these rows are built by JS after
   load, so the existing querySelectorAll-once helper never sees them.
   Delegating from document covers both. */
(function () {
  var SEL = '.av-st-tabs, .cmp-scroll, .cmp-tabs, .icc-chips, .ic-tabs';
  var track = null, startX = 0, startScroll = 0, moved = false;

  document.addEventListener('pointerdown', function (e) {
    if (e.pointerType === 'touch') return;            /* native scrolling wins */
    var t = e.target.closest && e.target.closest(SEL);
    if (!t || t.scrollWidth <= t.clientWidth) return; /* nothing to scroll */
    track = t; moved = false;
    startX = e.clientX; startScroll = t.scrollLeft;
    t.style.cursor = 'grabbing';
  });
  document.addEventListener('pointermove', function (e) {
    if (!track) return;
    var dx = e.clientX - startX;
    if (Math.abs(dx) > 4) moved = true;
    track.scrollLeft = startScroll - dx;
  });
  function end() {
    if (!track) return;
    track.style.cursor = '';
    var t = track; track = null;
    /* a drag must not also fire the tile/chip underneath */
    if (moved) setTimeout(function () { moved = false; }, 0);
  }
  ['pointerup', 'pointercancel', 'pointerleave'].forEach(function (ev) {
    document.addEventListener(ev, end);
  });
  /* swallow the click that follows a drag, before anything else sees it */
  document.addEventListener('click', function (e) {
    if (!moved) return;
    if (!e.target.closest || !e.target.closest(SEL)) return;
    e.preventDefault(); e.stopPropagation();
  }, true);

  /* show the affordance only where there is something to drag */
  function cursors() {
    document.querySelectorAll(SEL).forEach(function (t) {
      t.style.cursor = t.scrollWidth > t.clientWidth ? 'grab' : '';
    });
  }
  window.addEventListener('load', cursors);
  window.addEventListener('resize', cursors, { passive: true });
  document.addEventListener('click', cursors);
})();

