/* ══════════════════════════════════════════════════════════════════════════
   STATUS-BAR COLOUR
   Installed to the Home Screen the status bar is transparent and the design
   draws through it, so this changes nothing there. In a plain Safari TAB the
   bar is browser chrome: left undeclared, Safari samples the top of the page
   and guesses — which is where the rust band came from, sampled off the
   blurred orange .home-glow.

   theme-color is one static value per document, and this prototype runs from a
   dark hero into white lists. So rather than pick one and be wrong half the
   time, sample the same data-nav-theme the tab bar already uses — but at the
   TOP of the viewport instead of the bottom.
   ══════════════════════════════════════════════════════════════════════════ */
(function () {
  var meta = document.querySelector('meta[name="theme-color"]');
  if (!meta) return;
  /* The tab bar's own themes, as colours. Anything unlabelled is a white list. */
  var THEME = {
    light: '#ffffff', dark: '#1B1B18', black: '#0b0b0a', video: '#0b0b0a',
    purple: '#5936c1', teal: '#00a8b1', rose: '#d5a2b9'
  };
  var last = '';
  function themeAtTop() {
    /* jsdom has no hit testing, and neither does a page that has not painted. */
    if (typeof document.elementFromPoint !== 'function') return 'light';
    var el = document.elementFromPoint(Math.round(window.innerWidth / 2), 4);
    while (el) {
      if (el.dataset && el.dataset.navTheme) return el.dataset.navTheme;
      el = el.parentElement;
    }
    return 'light';
  }
  function sync() {
    var c = THEME[themeAtTop()] || THEME.light;
    if (c !== last) { last = c; meta.setAttribute('content', c); }
  }
  window.setStatusBarColor = function (theme) {
    var c = THEME[theme] || THEME.light;
    if (c !== last) { last = c; meta.setAttribute('content', c); }
  };
  window.addEventListener('scroll', sync, { passive: true });
  window.addEventListener('resize', sync, { passive: true });
  /* Tab and screen changes move a whole layer under the status bar without
     scrolling anything, so watch the class flips too. */
  new MutationObserver(sync).observe(document.body, { attributes: true, attributeFilter: ['class'] });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', sync);
  else sync();
})();

