  var FAN_FADE  = 260;     /* art px — and at full strength from here out */

  var PRESETS = {
    /* glow is a SCREEN colour, so it is picked for what it does to #ff550c,
       not for how it looks on its own: rgb(255,152,116) at .42 lands the
       hotspot on about (255,127,60) — roughly 1.3x the card's brightness —
       while dim .38 puts everything outside the beam at about 0.62x. */
    /* A big soft pool rather than a spot: the wash barely darkens, the lift
       is gentle and wide, and the engraving is the one thing allowed to be a
       little brighter — it is what the light is there to show. */
    /* The light barely lifts the face at all now — what the beam does is
       EXPOSE, not brighten. So the engraving is struck in the card's own ink
       (#ff550c, opened up a little so it survives on black) and the glow is
       only there to say where the light is. */
    /* .12, was .05. glowFrom() takes this alpha and paints it in the CARD's own
       ink lifted halfway to white — which is already what Yuan asked for on 26
       Aug ("色彩的话还是要跟背景颜色相似，但是很浅"), so the colour is unchanged
       and only the amount moved: at .05 over a face at 17/255 the lift was
       under a twentieth of a stop and read as nothing. */
    warm: { dim: 0.30, glow: 'rgba(255,182,140,.12)', line: 'rgba(255,128,58,1)', alpha: 0.62 },
    cool: { dim: 0.32, glow: 'rgba(164,204,255,.12)', line: 'rgba(255,128,58,1)', alpha: 0.62 },
    grey: { pool: '#31353a', soft: 'rgba(49,53,58,.88)', line: '#e9edf1', alpha: 0.5 },
    blue: { pool: '#4fa3e9', soft: 'rgba(79,163,233,.88)', line: '#14232e', alpha: 0.55 }
  };
  var mode = (new URLSearchParams(location.search).get('uv') || 'warm').toLowerCase();
  if (!PRESETS[mode]) mode = 'warm';

  /* ── paint the extension ───────────────────────────────────────────────
     One canvas per card, at 2x, reused for every reveal. Rays are struck
     from the fan's own apex so they land on the printed ones; a
     destination-out wash fades the crowded inner end. */
