    /* ── the password generator ────────────────────────────────────────
       What it is set to, rather than what it hard-codes: Yuan asked for length
       and the character classes as controls in a tray (24 Aug), so the settings
       are state and genPass() reads them. Changing a toggle changes what the
       next reroll can produce.
       The alphabets are Day30-V1's PW_CHARS / PW_MARKS split by class so the
       toggles can address them, and they keep its exclusions — no l, I, O, 0 or
       1. A password you read off a screen and type on a phone cannot afford an
       ambiguous glyph. */
    var PW = { len: 17, letters: true, digits: true, symbols: true, phrase: false };
    var PW_L = 'abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ';
    var PW_D = '23456789';
    var PW_S = '#$%&!@*^.';
    var PW_W = ['brave', 'otter', 'maple', 'ember', 'quartz', 'harbor',
                'falcon', 'cobalt', 'willow', 'ranger', 'pepper', 'summit'];
    /* indexes strings and arrays alike, which is what lets phrase mode share it */
    function pwPick(s) { return s[Math.floor(Math.random() * s.length)]; }
    function genPass() {
      if (PW.phrase) {
        /* three words is the readable-and-still-long trade. The digits and
           symbols toggles become the joint and the tail, so they still mean
           something here rather than sitting in the tray being ignored. */
        var join = PW.symbols ? pwPick('-.!@') : '-';
        var w = [];
        while (w.length < 3) { var x = pwPick(PW_W); if (w.indexOf(x) < 0) w.push(x); }
        return w.join(join) + (PW.digits ? pwPick(PW_D) + pwPick(PW_D) : '');
      }
      var pool = (PW.letters ? PW_L : '') + (PW.digits ? PW_D : '') + (PW.symbols ? PW_S : '');
      /* The tray keeps one toggle on, so this is a guard rather than a state you
         can reach — but an unreachable branch that returns a password is better
         than one that returns nothing. */
      if (!pool) pool = PW_L;
      var n = Math.max(6, Math.min(40, PW.len | 0)), out = [], i;
      for (i = 0; i < n; i++) out.push(pwPick(pool));
      /* ...and one of each enabled class is guaranteed, at distinct positions.
         A pool draw can legally come back with no digit in it at all, and a
         generator that ignores its own settings some of the time is worse than
         one that has none. */
      var want = [];
      if (PW.letters) want.push(PW_L);
      if (PW.digits) want.push(PW_D);
      if (PW.symbols) want.push(PW_S);
      var slots = [], guard = 0;
      while (slots.length < Math.min(want.length, n) && guard++ < 200) {
        var k = Math.floor(Math.random() * n);
        if (slots.indexOf(k) < 0) slots.push(k);
      }
      slots.forEach(function (k, j) { out[k] = pwPick(want[j]); });
      return out.join('');
    }

    /* what Generate mints, per row id */
    function mint(id) {
      function d(n) { var o = ''; while (o.length < n) o += Math.floor(Math.random() * 10); return o; }
      if (id === 'pass') return genPass();
      if (id === 'user')  return 'orbit' + d(3) + '@myclkd.id';
      if (id === 'phone') return '425-' + d(3) + '-' + d(4);
      return d(6);
    }
