    /* "Free trial" is the first segment, exactly as Figma writes it
       (freetrial.newyorkillustrator.stayclkd.com) */
    function aeTitleSlug(title) {
      return (title || '').toLowerCase().replace(/[^a-z0-9]+/g, '').slice(0, 16);
    }
    /* The address is assembled, never stored: title + the variation the reroll
       is currently on + the domain it is currently on. Both indices advance on
       a tap, so the shape AND the domain move together. */
    /* Four digits derived from the opening's own fallback: deterministic, so the
       head holds still for as long as the fallback does, and numeric so it does
       not read as an echo of the middle segment — slicing the fallback itself
       gave "idjpjz.jpjzf9.cloaked.com". */
