    /* ── sparks: embers where the seam crosses the glyphs ───────────────── */
    var SPARKS = 80, SPARK_LIFE = 0.055, ROW_BAND = 54;
    var sparkSeed = Math.random() * 97;
    function hash(v) { var q = Math.sin(v) * 43758.5453; return q - Math.floor(q); }
