  /* A collapsed removal day opens in place. Delegated from the document so it
     survives any later re-render of the feed, and it walks forward only while
     the next sibling is still a detail row — that is what scopes a click to its
     own day without giving every group an id to match on. */
  (function removalDayStacks() {
    document.addEventListener('click', function (e) {
      var row = e.target && e.target.closest && e.target.closest('.av-row.is-stack');
      if (!row) return;
      var open = row.classList.toggle('is-open');
      var n = row.nextElementSibling;
      while (n && n.classList && n.classList.contains('av-row-detail')) {
        n.classList.toggle('is-shown', open);
        n = n.nextElementSibling;
      }
    });
  })();

